function bstFromPreorder(preorder) {
  let root = null;
  for (const value of preorder) {
    const fresh = new TreeNode(value);
    if (root === null) { root = fresh; continue; }
    let current = root;
    for (;;) {
      if (value < current.val) {
        if (!current.left) { current.left = fresh; break; }
        current = current.left;
      } else {
        if (!current.right) { current.right = fresh; break; }
        current = current.right;
      }
    }
  }
  return root;
}

