function generate(rand, size) {
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 8);
  const span = size === 'large' || rand() < 0.5 ? 1000 : 12;
  const pool = Array.from({ length: span }, (_, i) => i + 1);
  for (let i = pool.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [pool[i], pool[j]] = [pool[j], pool[i]];
  }
  const values = pool.slice(0, n);
  const shape = rand();
  if (shape < 0.1) values.sort((a, b) => a - b);
  else if (shape < 0.2) values.sort((a, b) => b - a);
  // Insert the values into a BST, then read the tree back in preorder.
  const root = { val: values[0], left: null, right: null };
  for (const v of values.slice(1)) {
    let current = root;
    for (;;) {
      const side = v < current.val ? 'left' : 'right';
      if (!current[side]) { current[side] = { val: v, left: null, right: null }; break; }
      current = current[side];
    }
  }
  const out = [], stack = [root];
  while (stack.length) {
    const node = stack.pop();
    if (!node) continue;
    out.push(node.val);
    stack.push(node.right, node.left);
  }
  return [out];
}

