function validate([preorder]) {
  if (preorder.length < 1 || preorder.length > 100) return 'preorder needs 1 to 100 values.';
  if (preorder.some(v => v < 1 || v > 1000)) return 'Each value is between 1 and 1000.';
  if (new Set(preorder).size !== preorder.length) return 'All values must be distinct.';
  // A valid BST preorder never drops below a value it has already moved to the right of.
  let low = -Infinity;
  const stack = [];
  for (const v of preorder) {
    if (v < low) return 'preorder must be the preorder traversal of some BST.';
    while (stack.length && stack[stack.length - 1] < v) low = stack.pop();
    stack.push(v);
  }
  return null;
}
